// Turns each Google Business Profile review into clean fields.
// A review's name looks like accounts/123/locations/456/reviews/AbC...
const STARS = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };

return $input.all().map((item, index) => {
  const review = item.json;
  const name = String(review.name ?? '');
  const parts = name.match(/^(accounts\/[^/]+)\/(locations\/[^/]+)\/reviews\/([^/]+)$/) ?? [];
  const reviewer = review.reviewer ?? {};
  const displayName = reviewer.isAnonymous ? '' : String(reviewer.displayName ?? '').trim();
  const firstName = /^a google user$/i.test(displayName) ? '' : displayName.split(/\s+/)[0] ?? '';

  return {
    json: {
      review_id: String(review.reviewId ?? parts[3] ?? ''),
      review_name: name,
      account: parts[1] ?? '',
      location: parts[2] ?? '',
      reviewer: displayName || 'A Google user',
      reviewer_first_name: firstName,
      rating: STARS[review.starRating] ?? 0,
      review_text: String(review.comment ?? '').trim(),
      review_created: review.createTime ?? '',
      has_reply: Boolean(review.reviewReply?.comment),
    },
    pairedItem: { item: index },
  };
});

