// Cleans the AI draft, decides which reviews need a manager's approval,
// and builds the Slack message for those reviews.
const MAX_REPLY = 4096; // Google's limit for a review reply
const MAX_SLACK_TEXT = 1100; // keeps the Slack message under Slack's 3,000 character limit

const shorten = (text, max) => (text.length > max ? text.slice(0, max).replace(/\s+\S*$/, '') + '...' : text);

const items = $input.all().map((item, index) => {
  const review = $('Settings').itemMatching(index).json;

  let draft = String(item.json.text ?? '').trim();
  draft = draft.replace(/^["“]+|["”]+$/g, '').trim(); // drop quotes wrapped around the whole reply
  if (draft.length > MAX_REPLY) draft = draft.slice(0, MAX_REPLY).replace(/\s+\S*$/, '');

  const minRating = Number(review.auto_post_min_rating);
  const threshold = Number.isFinite(minRating) ? minRating : 4;
  const needsApproval = !draft || review.rating < threshold;

  const stars = '★'.repeat(review.rating) + '☆'.repeat(5 - review.rating);
  const reviewText = review.review_text ? shorten(review.review_text, MAX_SLACK_TEXT) : '(No text, rating only)';
  const slackMessage = [
    `*New ${review.rating}-star Google review for ${review.business_name}*`,
    `${stars}  from ${review.reviewer}`,
    '',
    reviewText,
    '',
    '*Suggested reply:*',
    draft ? shorten(draft, MAX_SLACK_TEXT) : '(The AI did not return a reply. Write one in the form.)',
    '',
    'Click *Review reply* to post it, edit it first, or skip it.',
  ].join('\n');

  const formDescription = [
    `${review.rating}-star review from ${review.reviewer}:`,
    review.review_text || '(No text, rating only)',
    '',
    'Edit the reply below if needed, then choose what to do.',
  ].join('\n');

  return {
    json: {
      ...review,
      ai_draft: draft,
      needs_approval: needsApproval,
      slack_message: slackMessage,
      form_description: formDescription,
    },
    pairedItem: { item: index },
  };
});

// Post the replies that need no approval first, so they never wait behind a Slack approval.
items.sort((a, b) => Number(a.json.needs_approval) - Number(b.json.needs_approval));
return items;

// Reads the manager's answer from the Slack form.
// When the wait time runs out with no answer, Slack passes the review through without a "data" field.
const POST = 'Post this reply';
const review = $('Loop Over Reviews').item.json;
const answer = $json.data;
const clean = (text) => String(text ?? '').replace(/\r\n/g, '\n').trim();

let action = 'skip';
let decision = 'no response';
let finalReply = '';

if (answer) {
  const edited = clean(answer.reply);
  if (answer.decision === POST) {
    finalReply = (edited || clean(review.ai_draft)).slice(0, 4096);
    if (!finalReply) decision = 'skipped';
    else {
      action = 'post';
      decision = edited && edited !== clean(review.ai_draft) ? 'edited' : 'approved';
    }
  } else {
    decision = 'skipped';
  }
}

return {
  json: {
    ...review,
    action,
    final_reply: finalReply,
    decision,
    responded_at: answer?.respondedAt ?? '',
  },
};

// Builds one Google Sheets row per review, whichever path it took.
// decision: auto, approved, edited, skipped, no response
// status:   posted, test mode, not posted, error
const review = $('Route Reply').item.json;
const from = $prevNode.name;
const output = $prevNode.outputIndex;

let status = 'not posted';
let postedAt = '';
let error = '';

if (from === 'Post Reply to Google') {
  if (output === 0) {
    status = 'posted';
    postedAt = $json.updateTime ?? $now.toISO();
  } else {
    status = 'error';
    const err = $input.item.error ?? $json.error;
    error = String(err?.description ?? err?.message ?? err ?? 'Google did not accept the reply. Open the execution for details.');
  }
} else if (review.action === 'post') {
  status = 'test mode';
}

return {
  json: {
    review_id: review.review_id,
    location: review.location,
    reviewer: review.reviewer,
    rating: review.rating,
    review_text: review.review_text,
    review_created: review.review_created,
    ai_draft: review.ai_draft,
    final_reply: review.final_reply ?? '',
    decision: review.decision,
    status,
    posted_at: postedAt,
    error,
    logged_at: $now.toISO(),
  },
};
